    # Check which characters need to change
    min_len = min(len(inp), len(outp))
    for j in range(max(len(inp), len(outp))):
        char_in = inp[j] if j < len(inp) else None
        char_out = outp[j] if j < len(outp) else None

        if char_in != char_out:
            print(f"   Position {j}: '{char_in}' -> '{char_out}'")

print("\nLooking for patterns...")
# Check if we can identify simple replacement rules
replacements = {}

# Let's check what single character replacements could work
for inp, outp in zip(inputs, outputs):
    if inp == outp:
        continue
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            if inp[i] not in replacements:
                replacements[inp[i]] = outp[i]
            else:
                # Multiple mappings for same character - might be complex
                print(f"Conflict: '{inp[i]}' maps to both '{replacements[inp[i]]}' and '{outp[i]}'")

print(f"\nPotential single character replacements: {replacements}")

